        <div classname = "parent">
            <h2>ABOUT ME</h2>
            <div className="aboutSec">
                <div className = "leftSideAbout">
                    <p>insert headshot</p>
                    <div className = "edu">
                        <h3>Education</h3>
                        <img src={ubcLogo} alt="UBC logo" className = "ubcLogo" />
                        <h4>The University of British Columbia</h4>
                    <p>BSc. September 2024-August 2028</p>
                    </div>
                </div>
                <div className = "rightSideAbout">
                    <p>Lorem ipsum</p>   
                </div>
            </div>
        </div>
    );
  };
  
  export default About;
